function parseCastingTime(text) {
	const t = String(text || "").toLowerCase();
	if (!t) return {
		category: null,
		label: ""
	};
	if (t.includes("bonus")) return {
		category: "bonus",
		label: text
	};
	if (t.includes("reaction")) return {
		category: "reaction",
		label: text
	};
	if (t.includes("free")) return {
		category: "free",
		label: text
	};
	return {
		category: "action",
		label: text
	};
}
