//#region src/lib/rulebookStore.js
var KEY = "skilltree:rulebook";
var newChapterId = () => "ch" + Date.now() + "-" + Math.floor(Math.random() * 1e3);
var newBookId = () => "bk" + Date.now() + "-" + Math.floor(Math.random() * 1e3);
var DEFAULT_RULEBOOK = {
	title: "Rulebook",
	books: [{
		id: "bk-default",
		title: "Rulebook",
		chapters: [{
			id: "ch-quick-start",
			title: "Quick Start Guide",
			content: `# Quick Start Guide

Welcome, adventurer! This guide gets you playing in five minutes.

> ### The three pools
> - **Talent Points** — buy most talents on the tree
> - **Heritage Points** — buy your heritage's innate traits
> - **Attribute Points** — raise your ability scores

## 1. Get a tree
Pick **New** on the menu for a blank project, or **Load** to continue a saved character. Homebrew trees live in tabs along the top of the canvas.

## 2. Invest points
Open the **View** mode, click a node's **+** to invest, and the character sheet on the right updates live — stats, resources, actions and proficiencies all follow the tree.

## 3. Read the details
Hover a node for a summary, or **hold Alt** over a node to open its full description. Descriptions can carry links: type \`[[Node Name]]\` when editing to jump between notes, and \`[[Node Name / Subtree]]\` to open a subtree.

## 4. Design your own
- **Edit** mode — double-click empty canvas to create nodes, drag to arrange, right-click for options
- **Values** mode — tune the numbers: pools, level rules and the Reference Library
- **Homebuilder** — design the home, business or bastion your character lives in

## Writing your own rulebook

Chapters here are written in [Homebrewery](https://homebrewery.naturalcrit.com) markdown, so you can paste straight from your homebrew:

| You type | You get |
| --- | --- |
| \`# Title\` | A chapter heading |
| \`**bold**\`, \`*italics*\` | **bold**, *italics* |
| \`> quote\` | A highlighted callout |
| \`| a | b |\` rows | A table |

Use \\pagebreak between sections, keep one chapter per topic, and players can read everything from the **Rulebook** tab on their character screen.
`
		}, {
			id: "ch-credits",
			title: "Credits",
			credits: true,
			names: [],
			content: "# Credits\n\nAdd the project creator and collaborators here."
		}]
	}],
	activeBookId: "bk-default"
};
var creditsContent = (names = []) => `# Credits\n\n${names.length ? names.map((n) => `- ${n}`).join("\n") : "Add the project creator and collaborators here."}\n`;
function loadRulebook() {
	const ensureCredits = (rb) => {
		const first = rb?.books?.[0];
		if (!first || !Array.isArray(first.chapters)) return rb;
		if (first.chapters.some((c) => c.credits)) return rb;
		first.chapters.push({
			id: "ch-credits",
			title: "Credits",
			credits: true,
			names: [],
			content: creditsContent([])
		});
		return rb;
	};
	try {
		const saved = JSON.parse(localStorage.getItem(KEY) || "null");
		if (saved && Array.isArray(saved.books) && saved.books.length) return ensureCredits({
			title: "Rulebook",
			books: saved.books,
			activeBookId: saved.activeBookId || saved.books[0].id
		});
		if (saved && Array.isArray(saved.chapters) && saved.chapters.length) {
			const b = {
				id: "bk-migrated",
				title: saved.title || "Rulebook",
				chapters: saved.chapters
			};
			return ensureCredits({
				title: "Rulebook",
				books: [b],
				activeBookId: b.id
			});
		}
	} catch {}
	return JSON.parse(JSON.stringify(DEFAULT_RULEBOOK));
}
function saveRulebook(rb) {
	try {
		localStorage.setItem(KEY, JSON.stringify(rb));
	} catch {}
}
function setRulebookActiveBookId(id) {
	if (!id) return;
	try {
		const saved = JSON.parse(localStorage.getItem(KEY) || "null");
		if (saved && Array.isArray(saved.books)) {
			saved.activeBookId = id;
			localStorage.setItem(KEY, JSON.stringify(saved));
		}
	} catch {}
}
function addCreditNames(names = []) {
	const incoming = [...new Set((names || []).map((n) => String(n || "").trim()).filter(Boolean))];
	if (!incoming.length) return [];
	const rb = loadRulebook();
	const book = rb.books?.find((b) => b.chapters?.some((c) => c.credits)) || rb.books?.[0];
	if (!book) return [];
	const chapter = (book.chapters || []).find((c) => c.credits);
	const current = chapter ? [...chapter.names || []] : [];
	const seen = new Set(current.map((n) => n.toLowerCase()));
	const added = [];
	incoming.forEach((name) => {
		if (seen.has(name.toLowerCase())) return;
		seen.add(name.toLowerCase());
		current.push(name);
		added.push(name);
	});
	if (!added.length) return [];
	if (chapter) {
		chapter.names = current;
		chapter.content = creditsContent(current);
	} else book.chapters = [...book.chapters || [], {
		id: "ch-credits",
		title: "Credits",
		credits: true,
		names: current,
		content: creditsContent(current)
	}];
	saveRulebook(rb);
	try {
		window.dispatchEvent(new CustomEvent("skilltree:rulebook-credits", { detail: { names: added } }));
	} catch {}
	return added;
}
