function makeRng(seed) {
	let a = 0;
	const text = String(seed ?? "seed");
	for (let i = 0; i < text.length; i += 1) a = a * 31 + text.charCodeAt(i) | 0;
	const rand = () => {
		a |= 0;
		a = a + 1831565813 | 0;
		let t = Math.imul(a ^ a >>> 15, 1 | a);
		t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
		return ((t ^ t >>> 14) >>> 0) / 4294967296;
	};
	return {
		rand,
		int: (min, max) => min + Math.floor(rand() * (max - min + 1)),
		pick: (arr) => arr?.length ? arr[Math.floor(rand() * arr.length)] : "",
		chance: (p) => rand() < p,
		shuffle: (arr) => {
			const next = [...arr];
			for (let i = next.length - 1; i > 0; i -= 1) {
				const j = Math.floor(rand() * (i + 1));
				[next[i], next[j]] = [next[j], next[i]];
			}
			return next;
		}
	};
}
var syllable = (culture, part, rng) => rng.pick(SYLLABLES[culture]?.[part] || SYLLABLES.Human[part]);
function generatePersonName(culture = "Human", sex = "", rng = makeRng("name")) {
	const pool = SYLLABLES[culture] ? culture : "Human";
	const first = `${syllable(pool, "start", rng)}${rng.chance(.55) ? syllable(pool, "mid", rng) : ""}${syllable(pool, "end", rng)}`;
	const last = `${syllable(pool, "start", rng)}${syllable(pool, "end", rng)}`;
	const title = rng.chance(.22) ? rng.pick([
		"the Bold",
		"the Quiet",
		"the Younger",
		"the Elder",
		"of the Vale",
		"the Wanderer"
	]) : "";
	return {
		first,
		last,
		full: `${first} ${last}${title ? ` ${title}` : ""}`,
		sex
	};
}
function generateSettlementName(culture, rng, _kind = "town") {
	const base = generatePersonName(culture, "", rng).first;
	const suffix = rng.pick(PLACE_SUFFIXES.settlement);
	const prefix = rng.pick(PLACE_PREFIXES);
	const patterns = [
		`${base}${suffix}`,
		`${prefix} ${suffix}`,
		`${prefix}${suffix}`,
		`${base}'s ${suffix}`,
		`${base} ${rng.pick([
			"Crossing",
			"Landing",
			"Hollow",
			"Rest",
			"Watch",
			"Reach"
		])}`
	];
	return rng.pick(patterns);
}
function generateKingdomName(culture, rng, _kind = "kingdom") {
	const base = generatePersonName(culture, "", rng).first;
	const suffix = rng.pick(PLACE_SUFFIXES.kingdom);
	const prefix = rng.pick(PLACE_PREFIXES);
	const patterns = [
		`The ${prefix} ${suffix}`,
		`${base}${rng.pick([
			"ia",
			"land",
			"mark",
			"heim",
			"oria",
			"ath"
		])}`,
		`The ${suffix} of ${base}`,
		`${prefix} ${suffix}`,
		`${base}'s ${suffix}`
	];
	return rng.pick(patterns);
}
function generateRealmName(culture, rng, _kind = "realm") {
	const base = generatePersonName(culture, "", rng).first;
	const suffix = rng.pick(PLACE_SUFFIXES.realm);
	return rng.pick([
		`${base} ${suffix}`,
		`The ${rng.pick(PLACE_PREFIXES)} ${suffix}`,
		`${base}${rng.pick([
			"ar",
			"os",
			"ea",
			"um",
			"is"
		])}`,
		`The ${suffix} of ${base}`
	]);
}
function generateTavernName(rng) {
	return rng.pick([
		`The ${rng.pick([
			"Gilded",
			"Laughing",
			"Broken",
			"Sleeping",
			"Drunken",
			"Silver",
			"Black",
			"Red"
		])} ${rng.pick([
			"Griffin",
			"Crown",
			"Anchor",
			"Lantern",
			"Boar",
			"Dragon",
			"Cup",
			"Stag",
			"Wyrm",
			"Bell"
		])}`,
		`The ${rng.pick([
			"Prancing",
			"Wandering",
			"Hungry",
			"Singing"
		])} ${rng.pick([
			"Pony",
			"Bard",
			"Ogre",
			"Fox",
			"Kettle"
		])}`,
		`${rng.pick([
			"Mother",
			"Old",
			"Captain"
		])} ${generatePersonName("Human", "", rng).last}'s`
	]);
}
function generatePersonality(rng) {
	return {
		trait: rng.pick(TRAITS),
		ideal: rng.pick(IDEALS),
		bond: rng.pick(BONDS),
		flaw: rng.pick(FLAWS),
		quirk: rng.pick(QUIRKS),
		voice: rng.pick(VOICES),
		background: rng.pick(BACKGROUNDS)
	};
}
function occupationFor(role, settlementKind, rng) {
	if (OCCUPATIONS[role]) return rng.pick(OCCUPATIONS[role]);
	if (settlementKind === "capital" || settlementKind === "city") return rng.pick(OCCUPATIONS.city);
	if (settlementKind === "wilderness") return rng.pick(OCCUPATIONS.wilderness);
	return rng.pick(OCCUPATIONS.settlement);
}
function initialDisposition(role, rng) {
	if (role === "ruler" || role === "court") return "allied";
	const roll = rng.rand();
	if (roll > .86) return "friendly";
	if (roll > .64) return "trusting";
	if (roll > .16) return "indifferent";
	if (roll > .05) return "hostile";
	return "hated";
}
function generateNpc({ culture = "Human", role = "settlement", settlementKind = "town", rng, settlementId = "", nationId = "" }) {
	const sex = rng.pick([
		"female",
		"male",
		"nonbinary"
	]);
	const name = generatePersonName(culture, sex, rng);
	const age = rng.int(16, 72);
	const abilities = Object.fromEntries([
		"STR",
		"DEX",
		"CON",
		"INT",
		"WIS",
		"CHA"
	].map((key) => [key, rng.int(8, 16)]));
	const roleAbility = {
		Steward: "INT",
		Chancellor: "CHA",
		Architect: "WIS",
		General: "STR",
		Warden: "CON",
		"Counter-Intel": "DEX",
		Ruler: "CHA"
	}[role];
	if (roleAbility) abilities[roleAbility] = rng.int(14, 18);
	return {
		id: `npc_${Math.floor(rng.rand() * 1e9).toString(36)}`,
		name: name.full,
		first: name.first,
		last: name.last,
		sex,
		age,
		abilities,
		culture,
		role,
		occupation: occupationFor(role, settlementKind, rng),
		personality: generatePersonality(rng),
		disposition: initialDisposition(role, rng),
		settlementId,
		nationId,
		homeBuildingId: "",
		workBuildingId: "",
		status: "Alive",
		notes: ""
	};
}
