function developmentCostText(development) {
	return Object.entries(development?.cost || {}).map(([key, value]) => `${value} ${key.toUpperCase()}`).join(" + ") || "Free";
}
function canAffordDevelopment(kingdom, development) {
	return Object.entries(development?.cost || {}).every(([key, value]) => (kingdom?.counts?.[key] || 0) >= value);
}
function generateWorldDevelopments(world) {
	if (!world) return [];
	const rng = makeRng(`${world.id || world.seed}:developments`);
	const developments = [];
	(world.nations || []).forEach((nation) => {
		const kingdom = (world.kingdoms || []).find((item) => item.nationId === nation.id);
		const settlements = (world.settlements || []).filter((item) => item.nationId === nation.id);
		const biomes = new Set(settlements.map((settlement) => settlement.biome));
		const eraTech = Number(world.eraTech) || {
			medieval: 4,
			renaissance: 5,
			industrial: 6,
			modern: 7,
			space: 8,
			cosmos: 9
		}[world.eraId] || 4;
		const pool = [
			"open_market",
			"lookout_tower",
			"diplomatic_enclave",
			"wall",
			"observation_balloon"
		];
		if ([...biomes].some((biome) => WATER_BIOMES.has(biome))) pool.push("trade_port", "bridge_fort", "observation_balloon");
		if ([...biomes].some((biome) => [
			"hills",
			"mountains",
			"underground"
		].includes(biome))) pool.push("industrial_encampment", "military_encampment", "castle");
		if ([...biomes].some((biome) => DIFFICULT_BIOMES.has(biome))) pool.push("magical_nexus", "sacred_grove");
		if ((world.routes || []).some((route) => route.type === "Highway" || route.type === "Road")) pool.push("highway", "toll_booth");
		if (eraTech >= 5) pool.push("arcanum_simulacrum");
		if (eraTech >= 4 && (world.theme || "").toLowerCase().includes("dark")) pool.push("insurrectionists_operations");
		rng.shuffle([...new Set(pool)]).slice(0, rng.int(2, 4)).forEach((id) => {
			const development = DEVELOPMENT_BY_ID[id];
			if (!development) return;
			const site = developmentSiteFor(world, nation, development, rng);
			if (!site) return;
			if (developments.some((item) => distance(item, site) < 16)) return;
			developments.push({
				id: `dev_${world.id || "w"}_${id}_${developments.length}_${Math.floor(rng.rand() * 1e5)}`,
				typeId: id,
				name: development.name,
				category: development.category,
				nationId: nation.id,
				kingdomId: kingdom?.id || "",
				realmId: nation.realmId,
				x: site.x,
				y: site.y,
				biome: site.biome,
				biomeLabel: site.biomeLabel,
				terrain: development.terrain,
				status: "built",
				months: development.months,
				monthsRemaining: 0,
				builtTurn: kingdom?.turn || 1,
				benefit: development.benefit,
				mpDamage: development.mpDamage,
				armor: development.armor
			});
		});
	});
	return developments;
}
function placeDevelopment(worldInput, kingdomId, developmentId) {
	const world = JSON.parse(JSON.stringify(worldInput));
	const kingdom = (world.kingdoms || []).find((item) => item.id === kingdomId);
	const nation = (world.nations || []).find((item) => item.id === kingdom?.nationId);
	const development = DEVELOPMENT_BY_ID[developmentId];
	if (!kingdom || !nation || !development) return { error: "That development is not available to this kingdom." };
	if (!canAffordDevelopment(kingdom, development)) return { error: "The kingdom cannot afford that development." };
	const site = developmentSiteFor(world, nation, development, makeRng(`${world.id}:${developmentId}:${Date.now()}`));
	if (!site) return { error: `No valid ${development.terrain.toLowerCase()} site is available for ${development.name}.` };
	Object.entries(development.cost || {}).forEach(([key, value]) => {
		kingdom.counts[key] = Math.max(0, (kingdom.counts[key] || 0) - value);
	});
	const entry = {
		id: `dev_${Date.now().toString(36)}_${Math.floor(Math.random() * 1e5)}`,
		typeId: developmentId,
		name: development.name,
		category: development.category,
		nationId: nation.id,
		kingdomId: kingdom.id,
		realmId: nation.realmId,
		x: site.x,
		y: site.y,
		biome: site.biome,
		biomeLabel: site.biomeLabel,
		terrain: development.terrain,
		status: "building",
		months: development.months,
		monthsRemaining: development.months,
		startedTurn: kingdom.turn || 1,
		benefit: development.benefit,
		mpDamage: development.mpDamage,
		armor: development.armor
	};
	world.developments = [...world.developments || [], entry];
	world.logs = [...world.logs || [], {
		at: (/* @__PURE__ */ new Date()).toISOString(),
		text: `${kingdom.name} plants ${development.name} at ${site.biomeLabel} (${development.months} month${development.months === 1 ? "" : "s"}).`
	}];
	return {
		world,
		development: entry
	};
}
