	npc.schedule = [
		{
			start: 0,
			end: 6,
			place: "home",
			buildingId: npc.homeBuildingId || "",
			label: "Sleeping"
		},
		{
			start: 6,
			end: 8,
			place: "home",
			buildingId: npc.homeBuildingId || "",
			label: "Morning routine"
		},
		{
			start: 8,
			end: 18,
			place: "work",
			buildingId: npc.workBuildingId || "",
			label: "Working"
		},
		{
			start: 18,
			end: 21,
			place: "tavern",
			buildingId: tavern?.id || "",
			label: "Evening at the tavern"
		},
		{
			start: 21,
			end: 24,
			place: "home",
			buildingId: npc.homeBuildingId || "",
			label: "Sleeping"
		}
	];
