//#region src/lib/kingdom.js
function normalizeKingdomEconomy(kingdom) {
	if (!kingdom) return kingdom;
	kingdom.stats = { ...kingdom.stats || {} };
	kingdom.counts = { ...kingdom.counts || {} };
	[
		"economy",
		"military",
		"influence",
		"prosperity"
	].forEach((key) => {
		kingdom.stats[key] = Math.max(0, Number(kingdom.stats[key]) || 0);
	});
	[
		"ec",
		"mc",
		"ic",
		"pc"
	].forEach((key) => {
		kingdom.counts[key] = Math.max(0, Number(kingdom.counts[key]) || 0);
	});
	return kingdom;
}
function settlementFinance(world, province) {
	const settlement = (world?.settlements || []).find((item) => item.id === province?.settlementId);
	if (!settlement) return {
		name: province?.name || "Unknown",
		income: 0,
		upkeep: 0,
		net: 0
	};
	const buildings = settlement.buildings || [];
	const population = Number(settlement.population) || 0;
	const prosperity = Number(settlement.prosperity) || 0;
	const commerce = buildings.filter((building) => /Tavern|Inn|Market|Shop|Bakery|Blacksmith|Guild|Bank|Trade|Dock|Warehouse/.test(building.type || "")).length;
	const income = Math.round(population / 1e3 * (1 + prosperity / 4) + commerce * 2 + (settlement.kind === "capital" ? 12 : 0));
	const upkeep = buildings.length ? Math.round(buildings.length * .5 + (settlement.kind === "capital" ? 4 : 1)) : 0;
	return {
		name: settlement.name,
		income,
		upkeep,
		net: income - upkeep,
		settlementId: settlement.id,
		kind: "settlement"
	};
}
function applyLedger(kingdom, world, log) {
	if (!world) return;
	const lines = [];
	let income = 0;
	let costs = 0;
	(kingdom.provinces || []).forEach((province) => {
		const finance = settlementFinance(world, province);
		income += finance.income;
		costs += finance.upkeep;
		lines.push(finance);
	});
	(world.developments || []).forEach((development) => {
		if (development.kingdomId !== kingdom.id || development.status !== "built") return;
		const finance = DEVELOPMENT_FINANCE[development.typeId] || {
			income: 0,
			upkeep: 0
		};
		income += finance.income;
		costs += finance.upkeep;
		lines.push({
			name: development.name,
			income: finance.income,
			upkeep: finance.upkeep,
			net: finance.income - finance.upkeep,
			developmentId: development.id,
			kind: "development"
		});
	});
	const net = income - costs;
	kingdom.treasury = Math.max(0, (kingdom.treasury || 0) + net);
	kingdom.ledger = [...kingdom.ledger || [], {
		turn: kingdom.turn,
		month: kingdom.month,
		year: kingdom.year,
		lines,
		income,
		costs,
		net
	}].slice(-24);
	if (lines.length) log.push(`Ledger: +${income} gp income, -${costs} gp upkeep, net ${net >= 0 ? "+" : ""}${net} gp.`);
}
