		const dPower = battlePower(defender) + rng.int(1, 6) + defenceBonus(defender);
		const margin = aPower - dPower;
		log.push(`Round ${round}: ${attacker.name} ${aPower} vs ${defender.name} ${dPower} — ${margin >= 0 ? "the attacker presses" : "the defender holds"}.`);
